import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO

# Config styling
plt.style.use('ggplot')
sns.set_theme(style="whitegrid")

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# --- DATA CLEANING & PREP ---
df['price'] = pd.to_numeric(df['price'], errors='coerce')
df['Case_Size_mm'] = pd.to_numeric(df['Case_Size_mm'], errors='coerce')
df['condition'] = df['condition'].fillna('Unknown')
df['brand'] = df['brand'].str.title()

# --- MARKET OVERVIEW ---
total_listings = len(df)
total_brands = df['brand'].nunique()
total_countries = df['Country'].nunique()

brand_dist = df['brand'].value_counts()
condition_dist = df['condition'].value_counts()

# --- KPIs ---
median_price_brand = df.groupby('brand')['price'].median()

country_brand_median = df.groupby(['brand', 'Country'])['price'].median().reset_index()
spread_by_brand = country_brand_median.groupby('brand')['price'].agg(['max', 'min'])
spread_by_brand['spread'] = spread_by_brand['max'] - spread_by_brand['min']

case_size_corr = df['Case_Size_mm'].corr(df['price'])

seller_counts = df['Seller_ID'].value_counts()
total_sellers = len(seller_counts)
top_5_percent_cutoff = max(1, int(total_sellers * 0.05))
power_sellers = seller_counts.head(top_5_percent_cutoff).index
power_seller_listings = seller_counts.head(top_5_percent_cutoff).sum()
power_seller_concentration = (power_seller_listings / total_listings) * 100

avg_price_cond_brand = df.groupby(['brand', 'condition'])['price'].mean().unstack()
if 'New' in avg_price_cond_brand.columns and 'Used' in avg_price_cond_brand.columns:
    new_used_premium = ((avg_price_cond_brand['New'] - avg_price_cond_brand['Used']) / avg_price_cond_brand['Used']) * 100
else:
    new_used_premium = pd.Series(dtype=float)

df['is_power_seller'] = df['Seller_ID'].isin(power_sellers)

# --- VISUALIZATIONS ---
def get_base64_fig(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()

# 1. Brand Distribution & Condition Mix
fig1, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))
sns.countplot(data=df, x='brand', palette='viridis', ax=ax1, order=df['brand'].value_counts().index)
ax1.set_title('Listing Volume by Brand', fontsize=14)
ax1.set_ylabel('Number of Listings')

sns.countplot(data=df, x='condition', palette='magma', ax=ax2, order=df['condition'].value_counts().index)
ax2.set_title('Listing Volume by Condition', fontsize=14)
ax2.set_ylabel('Number of Listings')
fig1_b64 = get_base64_fig(fig1)

# 2. Brand-Level Pricing (Boxplot)
fig2, ax = plt.subplots(figsize=(10, 6))
sns.boxplot(data=df, x='brand', y='price', palette='viridis', showfliers=False, ax=ax)
ax.set_title('Price Distribution by Brand (Excl. Outliers)', fontsize=14)
ax.set_ylabel('Price (USD)')
fig2_b64 = get_base64_fig(fig2)

# 3. Geographic Pricing Arbitrage (Heatmap)
heatmap_data = country_brand_median.pivot(index='Country', columns='brand', values='price')
top_countries = df['Country'].value_counts().head(15).index
heatmap_data = heatmap_data.loc[heatmap_data.index.isin(top_countries)]

fig3, ax = plt.subplots(figsize=(10, 8))
sns.heatmap(heatmap_data, annot=True, fmt=".0f", cmap="YlGnBu", ax=ax, cbar_kws={'label': 'Median Price (USD)'})
ax.set_title('Median Price by Brand and Country (Top 15 Countries by Volume)', fontsize=14)
fig3_b64 = get_base64_fig(fig3)

# 4. Case Size Premium
fig4, ax = plt.subplots(figsize=(10, 6))
sns.scatterplot(data=df.dropna(subset=['Case_Size_mm']), x='Case_Size_mm', y='price', hue='brand', alpha=0.6, palette='viridis', ax=ax)
ax.set_title(f'Case Size vs Price (Correlation: {case_size_corr:.2f})', fontsize=14)
ax.set_xlabel('Case Size (mm)')
ax.set_ylabel('Price (USD)')
fig4_b64 = get_base64_fig(fig4)

# 5. Power Seller vs Normal Seller
fig5, ax = plt.subplots(figsize=(10, 6))
sns.boxplot(data=df, x='is_power_seller', y='price', hue='brand', palette='Set2', showfliers=False, ax=ax)
ax.set_title('Pricing Strategy: Power Sellers vs Regular Sellers', fontsize=14)
ax.set_xticklabels(['Regular Sellers', 'Power Sellers'])
ax.set_ylabel('Price (USD)')
ax.set_xlabel('')
fig5_b64 = get_base64_fig(fig5)

