"""
for brand in median_price_brand.index:
    med = median_price_brand[brand]
    avg = df[df['brand']==brand]['price'].mean()
    prem = new_used_premium.get(brand, 0)
    html_content += f"<tr><td>{brand}</td><td>${med:.2f}</td><td>${avg:.2f}</td><td>{prem:.1f}%</td></tr>"

html_content += f"""
            </table>
