    max_c = country_brand_median[country_brand_median['brand']==brand].sort_values('price', ascending=False).iloc[0]['Country']
    min_c = country_brand_median[country_brand_median['brand']==brand].sort_values('price', ascending=True).iloc[0]['Country']
